inputs = ['xbu', 'uxwkkg', 'kib', 'fjze', 'cv']
outputs = ['xhu', 'uxwkkvzw', 'kih', 'fjxwye', 'cv']

# Manual analysis of changes
changes = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changes.append((i, inp, outp))
        print(f"Change {i}: '{inp}' -> '{outp}'")

print("\nAnalyzing individual changes:")
for idx, inp, outp in changes:
    print(f"Input: '{inp}', Output: '{outp}'")
    # Find differences character by character
    min_len = min(len(inp), len(outp))
    diff_positions = []
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_positions.append(j)
    if len(outp) > len(inp):
        diff_positions.extend(range(len(inp), len(outp)))
    elif len(inp) > len(outp):
        diff_positions.extend(range(len(outp), len(inp)))

    print(f"  Differences at positions: {diff_positions}")

